@Override public Object getContent(DataSource ds) throws IOException {
  String enc=null;
  InputStreamReader is=null;
  try {
    enc=getCharset(ds.getContentType());
    is=new InputStreamReader(ds.getInputStream(),enc);
  }
 catch (  IllegalArgumentException iex) {
    try {
      is=new InputStreamReader(ds.getInputStream(),eu.faircode.email.UnknownCharsetProvider.charsetForMime(getCharset(ds.getContentType())));
    } catch (IllegalCharsetNameException | UnsupportedCharsetException e) {
      throw new IOException("Failed to create reader with fallback charset", e);
    }
  }
  try {
    int pos=0;
    int count;
    char buf[]=new char[1024];
    while ((count=is.read(buf,pos,buf.length - pos)) != -1) {
      pos+=count;
      if (pos >= buf.length) {
        int size=buf.length;
        if (size < 256 * 1024)         size+=size;
 else         size+=256 * 1024;
        char tbuf[]=new char[size];
        System.arraycopy(buf,0,tbuf,0,pos);
        buf=tbuf;
      }
    }
    return new String(buf,0,pos);
  }
  finally {
    try {
      is.close();
    }
 catch (    IOException ex) {
    }
  }
}
